#!/usr/bin/env bash
# Apply the network configuration of the emulator host (Debian 13, ifupdown),
# generated from config/wanemu.conf.
#   sudo ./scripts/setup_network.sh            apply
#   ./scripts/setup_network.sh --print         only print the generated files
#
# WARNING: the bridge ports lose their addresses. If you are connected over SSH
# through a future bridge port, the connection drops - use the management port.
set -euo pipefail
# shellcheck source=SCRIPTDIR/common.sh
. "$(dirname "$0")/common.sh"

offloads="gro off gso off tso off lro off"

interfaces() {
    cat <<EOF
# /etc/network/interfaces - WAN emulator host
# Generated by scripts/setup_network.sh from config/wanemu.conf

source /etc/network/interfaces.d/*

auto lo
iface lo inet loopback

# Management
EOF
    if [ -n "$MGMT_ADDRESS" ]; then
        echo "auto $MGMT_IF"
        echo "iface $MGMT_IF inet static"
        echo "    address $MGMT_ADDRESS"
        [ -n "$MGMT_GATEWAY" ] && echo "    gateway $MGMT_GATEWAY"
    else
        echo "allow-hotplug $MGMT_IF"
        echo "iface $MGMT_IF inet dhcp"
    fi
    cat <<EOF

# Bridge ports: no addresses, no IPv6, no offloads
iface $PORT_A inet manual
    post-up /usr/sbin/sysctl -qw net.ipv6.conf.$PORT_A.disable_ipv6=1

iface $PORT_B inet manual
    post-up /usr/sbin/sysctl -qw net.ipv6.conf.$PORT_B.disable_ipv6=1

# Emulator bridge
auto $BRIDGE
iface $BRIDGE inet manual
    bridge_ports $PORT_A $PORT_B
    bridge_stp off
    bridge_fd 0
    bridge_maxwait 0
    post-up /usr/sbin/sysctl -qw net.ipv6.conf.$BRIDGE.disable_ipv6=1
    post-up /usr/sbin/ip link set $PORT_A promisc on
    post-up /usr/sbin/ip link set $PORT_B promisc on
    post-up /usr/sbin/ethtool -K $PORT_A $offloads 2>/dev/null || true
    post-up /usr/sbin/ethtool -K $PORT_B $offloads 2>/dev/null || true
EOF
}

nm_unmanaged() {
    cat <<EOF
# /etc/NetworkManager/conf.d/99-emulator-unmanaged.conf
# Generated by scripts/setup_network.sh. Keeps NetworkManager away from the emulator interfaces.
[keyfile]
unmanaged-devices=interface-name:$MGMT_IF;interface-name:$PORT_A;interface-name:$PORT_B;interface-name:$BRIDGE
EOF
}

if [ "${1:-}" = "--print" ]; then
    echo "===== /etc/network/interfaces"; interfaces
    echo "===== /etc/NetworkManager/conf.d/99-emulator-unmanaged.conf"; nm_unmanaged
    echo "===== /etc/sysctl.d/99-emulator-bridge.conf"; cat "$ROOT/config/network/99-emulator-bridge.conf"
    exit 0
fi

[ "$(id -u)" = 0 ] || { echo "Run as root (sudo)." >&2; exit 1; }

STAMP="$(date +%Y%m%d-%H%M%S)"
cp -a /etc/network/interfaces "/etc/network/interfaces.bak-$STAMP"
interfaces > /etc/network/interfaces
if [ -d /etc/NetworkManager/conf.d ]; then
    nm_unmanaged > /etc/NetworkManager/conf.d/99-emulator-unmanaged.conf
    systemctl reload NetworkManager 2>/dev/null || true
fi
install -m 644 "$ROOT/config/network/99-emulator-bridge.conf" /etc/sysctl.d/99-emulator-bridge.conf

# Drop old addresses from the bridge ports
ip addr flush dev "$PORT_A" || true
ip addr flush dev "$PORT_B" || true

# Stop the DHCP client of the previous setup (Debian 13: dhcpcd, older: dhclient),
# otherwise it keeps a 169.254.x.x address and a default route on the management port.
if [ -n "$MGMT_ADDRESS" ]; then
    dhcpcd -x "$MGMT_IF" >/dev/null 2>&1 || true
    pkill -f "dhclient.*$MGMT_IF" || true
    ip addr flush dev "$MGMT_IF" || true
fi

systemctl restart networking

echo "Network configuration applied. Previous file: /etc/network/interfaces.bak-$STAMP"
